class Panel {
  private _title: HTMLElement | null = null;
  private _toolbar: HTMLElement | null = null;
  get title() {
    if (!this._title) this._title = document.createElement('h1');
    return this._title;
  }
  get toolbar() {
    if (!this._toolbar) this._toolbar = document.createElement('div');
    return this._toolbar;
  }
}

/* Version A */
class WidgetA {
  private _content: Node | null = null;
  get content() {
    if (!this._content) this._content = buildHeavyContent();
    return this._content;
  }
}

/* Version B */
class WidgetB {
  private content: Node;
  constructor(private factory: ContentFactory) {}
  initialize() { this.content = this.factory.build(); }
  getContent() { return this.content; }
}
